//go:build arm64

package floats

// maxAbsMulNEON is generated by maxabsmul_arm64_gen.go into maxabsmul_arm64.s:
// VFABS+VFMUL, a NaN product masked to +0, VFMAX. w has been sliced to len(v).
//
//go:noescape
func maxAbsMulNEON(v, w []float64) float64

func maxAbsMul(v, w []float64) float64 { return maxAbsMulNEON(v, w) }
